solution.evidence:
"settings": {
    "max_ngram_diff": "20",
    "number_of_shards": "1",
    "analysis": {
      "analyzer": {
        "book_name_analyzer": {
          "type": "custom",
          "char_filter": [
            "remove_whitespace",
            "remove_special_chars"
          ],
          "tokenizer": "ngram_tokenizer",
          "filter": [
            "lowercase"
          ]
        }
      },

"char_filter": {
  "remove_whitespace": {
    "type": "pattern_replace",
    "pattern": """\s+""",
    "replacement": ""
  },
  "remove_special_chars": {
    "type": "pattern_replace",
    "pattern": "[^a-zA-Z0-9가-힣]",
    "replacement": ""
  }
},

"tokenizer": {
  "ngram_tokenizer": {
    "type": "ngram",
    "token_chars": [
      "letter",
      "digit"
    ],
    "min_gram": "1",
    "max_gram": "20"
  }
}

optimizeDeps: {
  include: ['react-csv', 'dayjs'],
},

